mapper.insert:
INSERT INTO notification_delivery(
    notification_id, channel, status, recipient_contact, created_at
) VALUES(
    #{notificationId}, #{channel}, #{status}, #{recipientContact}, NOW()
)

mapper.select:
SELECT *
FROM notification_delivery
WHERE notification_id = #{notificationId}
AND channel = #{channel}

mapper.update:
UPDATE notification_delivery
SET status = #{status}
    , sent_at = #{sentAt}
    , fail_reason = #{failReason}
WHERE delivery_id = #{deliveryId}

UPDATE notification_delivery
SET read_at = #{readAt}
WHERE delivery_id = #{deliveryId}
    AND channel = 'IN_APP'
